const clientNav=[["Overview",LayoutDashboard],["Project brief",FileText],["Assets",FolderKanban],["Messages",MessageCircle],["Approvals",ShieldCheck],["Payments",CircleDollarSign]];
const adminNav=[["Action Center",LayoutDashboard],["Clients",Users],["Projects",FolderKanban],["Messages",MessageCircle],["Payments",CircleDollarSign]];
