  const send=async({content,attachment})=>{if(!user||(!content.trim()&&!attachment))return {error:"Write a message or choose a file."};const s=getSupabaseBrowserClient();let attachments=[];if(attachment){const fileResult=await uploadChatFile(s,user.id,attachment);if(fileResult.error)return fileResult;attachments=[fileResult.data];}const {data,error}=await s.from("messages").insert({project_id:brief?.id||thread.messages.at(-1)?.project_id||null,sender_id:user.id,recipient_id:thread.client.id,content:content.trim()||`Attached: ${attachment?.name||"file"}`,attachments}).select("id").single();if(!error){dispatchEmailEvent("new_message",data.id);await onSent();}return {error:error?.message};};
