function Header({n,title:head,copy}){return <div className={styles.stepHeader}><b>{n}</b><div><h3>{head}</h3><p>{copy}</p></div></div>}function Field({label,value,onChange,required,error,type="text",placeholder}){return <label className={cx(styles.field,error&&styles.fieldError)}><span>{label}{required&&<em>*</em>}</span><input type={type} value={value||""} onChange={e=>onChange(e.target.value)} placeholder={placeholder}/>{error&&<small>{error}</small>}</label>}function Area({label,value,onChange,placeholder}){return <label className={styles.field}><span>{label}</span><textarea value={value||""} onChange={e=>onChange(e.target.value)} placeholder={placeholder}/></label>}function Chips({options,selected,toggle}){return <div className={styles.chips}>{options.map(x=><button key={x} onClick={()=>toggle(x)} className={selected.includes(x)?styles.chipActive:""}>{selected.includes(x)&&<Check size={13}/>} {x}</button>)}</div>}
